cat > merge.py <<'EOF'
import json, pandas as pd
MAP = {"user_id":"user_id","id":"user_id","userId":"user_id",
       "email":"email","email_address":"email",
       "full_name":"name","name":"name","userName":"name",
       "registration_date":"created_date","created_at":"created_date","joined":"created_date",
       "status":"status","is_active":"status","active":"status"}
FIELDS = ["name","email","created_date","status"]

def to_status(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return None
    if isinstance(v,(bool,)) or str(v).lower() in ("true","false","1","0"):
        b = v if isinstance(v,bool) else str(v).lower() in ("true","1")
        return "active" if b else "inactive"
    return str(v)

def to_date(v):
    if v is None or (isinstance(v,float) and pd.isna(v)) or v == "": return None
    return pd.to_datetime(v).strftime("%Y-%m-%d")

def norm(df):
    df = df.rename(columns={c: MAP[c] for c in df.columns if c in MAP})
    out = {}
    for r in df.to_dict("records"):
        uid = int(r["user_id"])
        rec = {}
        for f in FIELDS:
            v = r.get(f)
            if f == "created_date": v = to_date(v)
            elif f == "status": v = to_status(v)
            elif v is not None and not (isinstance(v,float) and pd.isna(v)): v = str(v)
            else: v = None
            rec[f] = v
        out[uid] = rec
    return out

srcs = {
 "source_a": norm(pd.DataFrame(json.load(open("/data/source_a/users.json")))),
 "source_b": norm(pd.read_csv("/data/source_b/users.csv", dtype=str)),
 "source_c": norm(pd.read_parquet("/data/source_c/users.parquet")),
}
order = ["source_a","source_b","source_c"]
rows, conflicts = [], []
for uid in sorted(set().union(*[s.keys() for s in srcs.values()])):
    row = {"user_id": uid}
    for f in FIELDS:
        vals = {s: srcs[s][uid][f] for s in order if uid in srcs[s] and srcs[s][uid][f] is not None}
        sel = next(iter(vals.values()), None)
        row[f] = sel
        if len(set(vals.values())) > 1:
            conflicts.append({"user_id": uid, "field": f, "values": vals, "selected": sel})
    rows.append(row)
df = pd.DataFrame(rows, columns=["user_id","name","email","created_date","status"])
df["user_id"] = df["user_id"].astype("int64")
for c in ["name","email","created_date","status"]: df[c] = df[c].astype("object")
df.to_parquet("/app/merged_users.parquet", index=False)
json.dump({"total_conflicts": len(conflicts), "conflicts": conflicts}, open("/app/conflicts.json","w"), indent=2)
EOF
./envcp ./merge.py :/app/merge.py && ./envrun 'cd /app && python3 merge.py; echo exit=$?; python3 -c "import pandas as pd; d=pd.read_parquet(\"merged_users.parquet\"); print(d.dtypes); print(d.to_string())"; cat conflicts.json'
